import{z as s,x as d,o as t,c as A,q as l,j as r,D as e,d as i,s as B,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"鲁宾斯坦轮流出价","description":"","frontmatter":{"title":"鲁宾斯坦轮流出价","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/rubinstein-bargaining.md","filePath":"econ/rubinstein-bargaining.md","lastUpdated":1791063341000}'),p={name:"econ/rubinstein-bargaining.md"};function m(u,a,c,h,b,C){const n=d("Mermaid");return t(),A("div",null,[a[2]||(a[2]=l('<h1 id="鲁宾斯坦轮流出价" tabindex="-1">鲁宾斯坦轮流出价 <a class="header-anchor" href="#鲁宾斯坦轮流出价" aria-label="Permalink to &quot;鲁宾斯坦轮流出价&quot;">​</a></h1><div class="epigraph"><p>无限期轮流出价、共同贴现的唯一子博弈完美均衡，在回合间隔趋于零时逼近纳什讨价还价解。</p><footer>—— Rubinstein, Perfect Equilibrium in a Bargaining Model, Econometrica, 1982</footer></div><p><a href="/econ/nash-bargaining">上一课</a>用公理钉住纳什积，但没有出价程序，\\(d\\) 从哪来也不回答。缺口是非合作实施：两人轮流提议分割，拒则过一期、贴现，SPE 是什么？Rubinstein 1982 给出唯一 SPE，耐心接近时逼近纳什解。本课钉这条程序，不重写四条公理。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一块大小为 \\(1\\) 的剩余，无限期。奇数期玩家 1 提议 \\((x,1-x)\\)，2 接受则结束，拒绝则进入下一期由 2 提议。共同贴现因子 \\(\\delta\\in(0,1)\\)（或每人 \\(\\delta_i\\)）。每过一期，饼乘 \\(\\delta\\)。</p><p>平稳 SPE：提议者总出同一分割，回应者接受当且仅当份额不少于自己当提议者时的贴现值。解出提议者所得</p> \\[x^*=\\frac{1-\\delta_2}{1-\\delta_1\\delta_2} \\]<p>（对称 \\(\\delta_1=\\delta_2=\\delta\\) 时 \\(x^*=1/(1+\\delta)\\)）。先手优势随 \\(\\delta\\to 1\\) 消失，\\(x^*\\to 1/2\\)，正是 \\(d=0\\)、对称可行集上的纳什解。\\(\\delta_1\\neq\\delta_2\\) 时，更耐心者多得，对应广义纳什积的权。</p><p><span class="marginnote">数字实例：对称 \\(\\delta=0.9\\) 时先手得 \\(1/(1+0.9)\\approx0.526\\)，只比一半多 2.6 个百分点；\\(\\delta=0.5\\)（很不耐烦）时先手得 \\(1/1.5\\approx0.667\\)。先手优势只有在双方都没耐心时才明显；大家都有耐心，谈判结果就接近对半。</span></p><h3 id="不是有限期从尾部拆掉的那一个" tabindex="-1">不是有限期从尾部拆掉的那一个 <a class="header-anchor" href="#不是有限期从尾部拆掉的那一个" aria-label="Permalink to &quot;不是有限期从尾部拆掉的那一个&quot;">​</a></h3><p>有限期轮流出价也可以逆向归纳，最后一期提议者拿全部，往前折。期限 \\(T\\to\\infty\\) 时收敛到同一平稳 SPE。无限期的要点是：没有「最后通牒」当终点，唯一性靠平稳猜测加 SPE，而不是蜈蚣式的终点。上一课<a href="/econ/backward-induction-limits">逆向归纳的限度</a>在有限完美信息上发脆；这里无限加贴现，归纳换成「每一截子博弈仍是同一结构」。</p><p><span class="marginnote">Binmore–Rubinstein–Wolinsky 把回合间隔写成 \\(\\Delta\\)，贴现 \\(e^{-r_i\\Delta}\\)。\\(\\Delta\\to 0\\) 时 SPE 分割趋于广义纳什积，权等于 \\(r_j\\)（对方更急则自己多得）。公理解得到非合作基础。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：完全信息、完美监测、不可撤回的提议、共同知识贴现。先猜平稳策略，用两方程（各人无差异于「拒然后自己提议」）解出 \\((x^*,y^*)\\)，再验证任何偏离——开出更贪的价会被拒，开出更让的价自己吃亏，拒绝该接受的价损失贴现。这是 SPE，不是仅仅根上的纳什。</p><p>外部选择 \\(d\\) 可以写进「拒绝后去外面」；无外部选择时 \\(d=0\\) 是延迟的机会成本。本课主钉 \\(d=0\\) 的饼。</p>',15)),(t(),r(o,null,{default:e(()=>[B(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20AX%5B%22%E7%BA%B3%E4%BB%80%E7%A7%AF%EF%BC%9A%E5%85%AC%E7%90%86%E8%A7%A3%22%5D%20--%3E%20ALT%5B%22%E8%BD%AE%E6%B5%81%E6%8F%90%E8%AE%AE%20%2B%20%E8%B4%B4%E7%8E%B0%22%5D%0A%20%20ALT%20--%3E%20SPE%5B%22%E5%94%AF%E4%B8%80%E5%B9%B3%E7%A8%B3%20SPE%22%5D%0A%20%20SPE%20--%3E%20LIM%5B%22%CE%B4%20%E2%86%92%201%20%E6%88%96%20%CE%94%20%E2%86%92%200%EF%BC%9A%E9%80%BC%E8%BF%91%E7%BA%B3%E4%BB%80%E8%A7%A3%22%5D%0A%20%20SPE%20--%3E%20PAT%5B%22%E6%9B%B4%E8%80%90%E5%BF%83%E8%80%85%E5%A4%9A%E5%BE%97%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[i("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"等待有成本，所以「永远拒绝」不可信：拖延伤害双方。提议者必须刚好让回应者无差异于再等一期——回应者的 SPE 续值被贴现，剩下的归提议者。这把时间偏好直接写成分割，不必另设威胁点上的效用积。\\(\\delta\\) 高，等得起，先手只能少拿一点；\\(\\delta_i\\) 相对更大，等于对方等不起，自己的续值高。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：谈判桌上放着一块会缩水的蛋糕，每拖一轮按 \\(\\delta\\) 折价。「永远不成交」对双方都是灾难，这种威胁不可信；真正起作用的是「再等一轮的代价」。谁等得起，谁就多分——耐心本身就是筹码。")],-1)),(t(),r(o,null,{default:e(()=>[B(n,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20OFF%5B%22%E7%8E%A9%E5%AE%B6%201%20%E6%8F%90%E8%AE%AE%EF%BC%9A2%20%E6%8B%BF%20y%EF%BC%8C1%20%E6%8B%BF%201-y%22%5D%20--%3E%20CMP%5B%222%20%E6%AF%94%E8%BE%83%EF%BC%9A%E6%8E%A5%E5%8F%97%20y%EF%BC%8C%E8%BF%98%E6%98%AF%E6%8B%92%E7%BB%9D%E5%90%8E%E8%87%AA%E5%B7%B1%E6%8F%90%E8%AE%AE%22%5D%0A%20%20CMP%20--%3E%20CON%5B%22%E6%8B%92%E7%BB%9D%E7%9A%84%E7%BB%AD%E5%80%BC%20%3D%20%CE%B42%20%C3%97%20%E8%87%AA%E5%B7%B1%E4%B8%8B%E4%B8%80%E6%9C%9F%E6%8F%90%E8%AE%AE%E6%89%80%E5%BE%97%22%5D%0A%20%20CON%20--%3E%20IND%5B%22%E5%9D%87%E8%A1%A1%EF%BC%9Ay%20%E6%81%B0%E5%A5%BD%E7%AD%89%E4%BA%8E%E8%BF%99%E4%B8%AA%E7%BB%AD%E5%80%BC%EF%BC%8C2%20%E6%97%A0%E5%B7%AE%E5%BC%82%22%5D%0A%20%20IND%20--%3E%20SYM%5B%22%E5%AF%B9%E7%A7%B0%E5%9C%B0%E5%86%99%201%20%E7%9A%84%E6%97%A0%E5%B7%AE%E5%BC%82%E6%9D%A1%E4%BB%B6%22%5D%0A%20%20SYM%20--%3E%20SOL%5B%22%E4%B8%A4%E5%BC%8F%E8%81%94%E7%AB%8B%EF%BC%8C%E8%A7%A3%E5%87%BA%E5%94%AF%E4%B8%80%E5%88%86%E5%89%B2%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p>与无名氏的对照：重复博弈有许多 SPE 分赃；轮流出价的树加上贴现，SPE 瘦到一个点。结构差异是「谈的是一次性分割」而不是「每期再玩阶段博弈」。同一套 SPE 定义，树不同，肥瘦不同。</p><h3 id="不完全信息会重新变肥" tabindex="-1">不完全信息会重新变肥 <a class="header-anchor" href="#不完全信息会重新变肥" aria-label="Permalink to &quot;不完全信息会重新变肥&quot;">​</a></h3><p>估值私有时，出价成为信号，延迟可以分离，效率损失（谈太久）是信息租金的另一种形式。那是类型，不是本课。有限 \\(T\\) 的最后通牒实验常偏离归纳（提议者拿不到全部），与蜈蚣同类：认知与公平参照，不是 Rubinstein 无限期公式算错。</p><p><span class="marginnote"> Stahl 有限期模型是教学台阶：从最后一期往前，分割振荡并收敛到无限期点。Rubinstein 直接在无限树上做。两者极限一致，不必当成两个理论。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>多边、蛋糕缩水方式非几何贴现、可同时提议，唯一性会掉。重新谈判若允许「推翻已接受的分割」，那是另一棵树。也不要把轮流出价写成限价簿的买卖价差收敛；本栏没有队列。</p><p>后课离开完全信息讨价还价，进入类型未知：贝叶斯纳什把「不知道对方支付」写成自然抽类型。本课默认：完全信息轮流出价的 SPE 分割由贴现决定，连续时间极限对接纳什积。</p><p><span class="marginnote">常见误区：实验里最后通牒的提议者常常拿不到理论上的大头，这不是公式算错——那是有限期实验里公平感与情绪在起作用。无限期模型里本来就没有「拿全部」的极端：\\(\\delta\\) 接近 1 时分割接近对半，先手优势随耐心消失。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>公理解没有程序；轮流出价给出唯一 SPE 分割。</li><li>对称时提议者得 \\(1/(1+\\delta)\\)；\\(\\delta\\to 1\\) 均分。</li><li>更耐心者多得；\\(\\Delta\\to 0\\) 逼近广义纳什积。</li><li>一次性分饼的树把 SPE 削瘦，与无名氏的肥集合不同构。</li><li>出处：Rubinstein, <em>Econometrica</em>, 1982；Binmore, Rubinstein and Wolinsky, <em>Rand</em>, 1986。</li></ul>',10))])}const D=s(p,[["render",m]]);export{_ as __pageData,D as default};
